/// <summary>
/// MPJ_18994 BYOD comparison
/// Class <c>METBYODCompHelper</c> to control BYOD population table by assisting the service class
/// </summary>
class METBYODCompHelper
{
    TableName       tableName;
    METNumOfRecords numOfRecords;
    METMaxRecId     maxRecId;
    CreatedDateTime createdDateTime;
    DataAreaId      legalEntity;

}

Method.Source:
/// <summary>
/// constructor
/// </summary>
/// <returns></returns>
public static METBYODCompHelper construct()
{
    return new METBYODCompHelper();
}

    /// <summary>
    /// run method tp execute the logic
    /// </summary>
    public void run()
    {
        METBYODComp ByodComp;

        delete_from ByodComp;

        this.populateBYODCompTable();
    }

/// <summary>
/// All inserts are seperated by appropriate method
/// </summary>
public void populateBYODCompTable()
{
    this.GeneralJournalAccountEntryAllCompanies();
    this.BudgetRegisterEntryAllCompanies();
    this.CustInvoiceJournalLine();
    this.CustomerPaymentJournalLine();
    this.CustTrans();
    this.DisputedInvoicesCrossCompany();
    this.VendInvoiceJournalLine();
    this.VendorInvoiceLine();
    this.VendorPaymentJournalLine();
    this.VendSettlementCrossCompany();
    this.VendTrans();
    this.TaxTrans();
    this.LedgerJournalTrans();
}

    /// <summary>
    /// General journal account entry insertion
    /// </summary>
    public void GeneralJournalAccountEntryAllCompanies()
    {        
        METGeneralJournalAccountEntryAllCompaniesStaging    generalJournalAccountEntryAllCompanies;

        select count(RecId) from generalJournalAccountEntryAllCompanies;
        numOfRecords = generalJournalAccountEntryAllCompanies.recid;

        select maxof(RecId) from generalJournalAccountEntryAllCompanies;
        maxRecId = generalJournalAccountEntryAllCompanies.RecId;

        tableName = tableStr(METGeneralJournalAccountEntryAllCompaniesStaging);
        createdDateTime = DateTimeUtil::getSystemDateTime(); 
        
        this.insertBYODTable(tableName, numOfRecords, maxRecId, createdDateTime);
    }

