/// <summary>
/// insertion in BYOD Table insertion
/// </summary>
public void insertBYODTable(TableName _tableName, METNumOfRecords _numOfRecords, METMaxRecId _maxRecID, CreatedDateTime _createdDateTime)
{
    METBYODComp metBYODComp;
    ttsbegin;
    metBYODComp.TableName       = _tableName;
    metBYODComp.NumOfRecords    = _numOfRecords;
    metBYODComp.MaxRecId        = _maxRecID;
    metBYODComp.ExtractedDate   = _createdDateTime;
    metBYODComp.insert();
    ttscommit;
}
